parameters.jsCode:
const r = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!r || !r.id) {
  return [{ json: { _error: 'UPDATE_NOT_FOUND', _status: 404, _details: 'update_id no existe o sin acceso por RLS' } }];
}
if (r.status === 'sent') {
  return [{ json: { _error: 'ALREADY_SENT', _status: 409, _details: 'Este resumen ya fue enviado al cliente' } }];
}
if (sess.action === 'reject') {
  return [{ json: {
    _branch: 'reject', ...sess,
    update_id: r.id, project_id: r.project_id, project_name: r.project_name
  }}];
}
const toEmail = sess.email_override || r.client_email;
if (!toEmail || !toEmail.includes('@')) {
  return [{ json: { _error: 'NO_CLIENT_EMAIL', _status: 400, _details: 'Cliente sin email valido. Usa email_override en el body' } }];
}
let photos = {};
try { photos = typeof r.photos_referenced === 'string' ? JSON.parse(r.photos_referenced) : (r.photos_referenced || {}); } catch (e) {}
const hitos = Array.isArray(photos.hitos_principales) ? photos.hitos_principales : [];
const proxima = photos.proxima_semana || '';
return [{ json: {
  _branch: 'approve', ...sess,
  update_id: r.id, project_id: r.project_id, project_name: r.project_name,
  current_phase: r.current_phase, location_city: r.location_city,
  week_start: String(r.week_start).slice(0,10),
  week_end: String(r.week_end).slice(0,10),
  summary_text: r.summary_text, hitos_principales: hitos, proxima_semana: proxima,
  client_name: r.client_name, client_email: toEmail
}}];

